def min_moves_to_a_good_string(n, s):
    def count_changes(start, end, char):
        changes = 0
        for i in range(start, end):
            if s[i] != char:
                changes += 1
        return changes

    def is_a_good_string(start, end):
        mid = (start + end) // 2
        if start == end:
            return s[start] == 'a'
        first_half_char = s[mid] if is_a_good_string(start, mid) else None
        second_half_char = s[mid] if is_a_good_string(mid, end) else None
        if first_half_char == 'a':
            return True
        if second_half_char == 'a':
            return True
        return False

    def solve(start, end):
        if start == end:
            return 0 if s[start] == 'a' else 1
        mid = (start + end) // 2
        first_half_char = s[mid] if is_a_good_string(start, mid) else None
        second_half_char = s[mid] if is_a_good_string(mid, end) else None
        if first_half_char == 'a':
