        if second_half_char == 'a':
            return solve(start, mid)
        changes_in_first_half = count_changes(start, mid, first_half_char)
        changes_in_second_half = count_changes(mid, end, second_half_char)
        return min(changes_in_first_half, changes_in_second_half)

    return solve(0, n - 1)

