from typing import List

def solve(n: int, m: int, removed: List[str]) -> str:
    k = 2 ** m - n
    half_index = k // 2

    def binary_to_decimal(binary: str) -> int:
        return int(binary, 2)

    def decimal_to_binary(num: int) -> str:
        return bin(num)[2:].zfill(m)

    def is_removed(num: int) -> bool:
        return decimal_to_binary(num) in removed

    candidates = [binary_to_decimal('0' * m + format(i, 'b').zfill(m)) for i in range(k)]
    candidates = [c for c in candidates if not is_removed(c)]

    return decimal_to_binary(half_index)

